const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const adj = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < m; i++) {
  const u = tok[2 + 2 * i], v = tok[3 + 2 * i];
  adj[u].push([v, i]);
  adj[v].push([u, i]);
}
const tin = new Array(n + 1).fill(0), low = new Array(n + 1).fill(0);
const pe = new Array(n + 1).fill(-1), nxt = new Array(n + 1).fill(0);
let timer = 0;
const bridges = [];
for (let s = 1; s <= n; s++) {
  if (tin[s]) continue;
  tin[s] = low[s] = ++timer;
  const stack = [s];
  while (stack.length) {
    const v = stack[stack.length - 1];
    if (nxt[v] < adj[v].length) {
      const [to, e] = adj[v][nxt[v]++];
      if (e === pe[v]) continue;
      if (tin[to]) low[v] = Math.min(low[v], tin[to]);
      else {
        tin[to] = low[to] = ++timer;
        pe[to] = e;
        stack.push(to);
      }
    } else {
      stack.pop();
      if (stack.length) {
        const p = stack[stack.length - 1];
        low[p] = Math.min(low[p], low[v]);
        if (low[v] > tin[p]) bridges.push(pe[v] + 1);
      }
    }
  }
}
bridges.sort((a, b) => a - b);
console.log([bridges.length, ...bridges].join("\n"));

