import java.io.*;
import java.util.*;

public class Main {
    static List<int[]>[] adj;
    static int[] tin, low;
    static int timer = 0;
    static List<Integer> bridges = new ArrayList<>();

    static void dfs(int v, int parentEdge) {
        tin[v] = low[v] = ++timer;
        for (int[] ed : adj[v]) {
            int to = ed[0], e = ed[1];
            if (e == parentEdge) continue;
            if (tin[to] != 0) {
                low[v] = Math.min(low[v], tin[to]);
            } else {
                dfs(to, e);
                low[v] = Math.min(low[v], low[to]);
                if (low[to] > tin[v]) bridges.add(e + 1);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            in.nextToken();
            int u = (int) in.nval;
            in.nextToken();
            int v = (int) in.nval;
            adj[u].add(new int[]{v, i});
            adj[v].add(new int[]{u, i});
        }
        tin = new int[n + 1];
        low = new int[n + 1];
        for (int s = 1; s <= n; s++) if (tin[s] == 0) dfs(s, -1);
        Collections.sort(bridges);
        StringBuilder out = new StringBuilder();
        out.append(bridges.size()).append('\n');
        for (int b : bridges) out.append(b).append('\n');
        System.out.print(out);
    }
}

